    inputDir: process.env.INPUT_DIR || core.getInput("input_dir"),
    outputDir: process.env.OUTPUT_DIR || core.getInput("output_dir"),
    forceRegenerate:
      (process.env.FORCE_REGENERATE || core.getInput("force_regenerate")) ===
      "true"
